questionvariables.text:
/* Random edge length of the regular tetrahedron (the ratios do not depend on it) */
a: 2+rand(9);

/* Distance from the centre O to each vertex */
OA: a*sqrt(6)/4;

/* Length of edge AB */
AB: a;

/* Cosine rule applied to triangle AOB */
ta_cos: (OA^2+OA^2-AB^2)/(2*OA^2);

/* Exact trigonometric ratios */
ta_sin: 2*sqrt(2)/3;
ta_tan: -2*sqrt(2);

/* Quadrant containing the angle, and the dropdown options */
ta_quad: 2;
quad_opts: [[1, false, "Quadrant I"], [2, true, "Quadrant II"], [3, false, "Quadrant III"], [4, false, "Quadrant IV"]];

/* Possible student mistakes */
cos_wrongsign: -ta_cos;
cos_height: 1/4;          /* used the height a*sqrt(6)/3 in place of OA */
sin_wrongsign: -ta_sin;
sin_nosqrt: 8/9;          /* forgot the square root */
tan_wrongsign: -ta_tan;
tan_recip: 1/ta_tan;      /* cos/sin instead of sin/cos */
